USE grievancehub;

INSERT INTO departments(department_name,description) VALUES
('Computer Science and Engineering','CSE department'),
('Hostel Administration','Hostel-related grievances'),
('Electrical Maintenance','Electrical and power maintenance');

INSERT INTO categories(category_name,description) VALUES
('Hostel','Hostel facilities and maintenance'),
('Mess','Food and mess services'),
('Electrical','Power and electrical issues'),
('Network','Internet and connectivity issues'),
('Academic','Academic and classroom concerns');

INSERT INTO users(name,email,password_hash,role) VALUES
('Demo Student','student.demo@example.test','REPLACE_WITH_BCRYPT_HASH','STUDENT'),
('Demo Staff','staff.demo@example.test','REPLACE_WITH_BCRYPT_HASH','STAFF'),
('Demo Admin','admin.demo@example.test','REPLACE_WITH_BCRYPT_HASH','ADMIN');

INSERT INTO students(user_id,roll_number,department_id,year_of_study,address)
SELECT u.user_id,'DEMO-ROLL-001',d.department_id,3,'Demo address'
FROM users u JOIN departments d ON d.department_name='Computer Science and Engineering'
WHERE u.email='student.demo@example.test';

INSERT INTO staff(user_id,employee_id,department_id,designation,address)
SELECT u.user_id,'DEMO-EMP-001',d.department_id,'Maintenance Coordinator','Demo office'
FROM users u JOIN departments d ON d.department_name='Hostel Administration'
WHERE u.email='staff.demo@example.test';

INSERT INTO complaints(student_id,category_id,department_id,title,description,location,priority,current_status)
SELECT s.user_id,cat.category_id,d.department_id,'Demo complaint - water supply',
       'Water supply issue reported for database testing.','Hostel Block A','MEDIUM','SUBMITTED'
FROM students s
JOIN users u ON u.user_id=s.user_id
JOIN categories cat ON cat.category_name='Hostel'
JOIN departments d ON d.department_name='Hostel Administration'
WHERE u.email='student.demo@example.test';

INSERT INTO complaint_history(complaint_id,changed_by,old_status,new_status,remarks)
SELECT c.complaint_id,c.student_id,NULL,'SUBMITTED','Complaint submitted'
FROM complaints c
WHERE c.title='Demo complaint - water supply'
  AND c.description='Water supply issue reported for database testing.';
